import streamlit as st
import streamlit.components.v1 as components
import base64, json
from pathlib import Path

st.set_page_config(page_title="接香菸大作戰", page_icon="🎮", layout="wide")

# 圖片已直接嵌入程式，不需要另外下載 PNG
default_player = "data:image/png;base64,"
default_cigarette = "data:image/png;base64,"

st.markdown("""
<style>
.stApp{background:linear-gradient(135deg,#10152d,#252044);color:white}
h1{color:#ffd166;text-align:center}
.note{text-align:center;color:#d8dcef}
</style>
""", unsafe_allow_html=True)

st.markdown("# 🎮 接香菸大作戰")
st.markdown('<p class="note">預設已載入右邊女生角色與單支香菸素材。</p>', unsafe_allow_html=True)

with st.expander("更換圖片（選填）"):
    c1,c2=st.columns(2)
    with c1:
        pf=st.file_uploader("更換人物圖片", type=["png","jpg","jpeg"])
    with c2:
        cf=st.file_uploader("更換掉落物圖片", type=["png","jpg","jpeg"])

def uploaded_uri(file, fallback):
    if file is None:
        return fallback
    encoded=base64.b64encode(file.getvalue()).decode("utf-8")
    return f"data:{file.type};base64,{encoded}"

player_js=json.dumps(uploaded_uri(pf, default_player))
cig_js=json.dumps(uploaded_uri(cf, default_cigarette))

html = r"""
<!DOCTYPE html><html lang="zh-Hant"><head><meta charset="UTF-8">
<style>
*{box-sizing:border-box}
body{margin:0;background:#10152d;color:white;font-family:Arial,sans-serif;text-align:center}
.wrap{max-width:900px;margin:auto;padding:10px}
.stats{display:flex;gap:8px;margin:8px 0 12px}
.stat{flex:1;background:#272e50;padding:10px 4px;border-radius:12px;border:1px solid #515d89;font-size:14px}
.stat b{display:block;color:#ffd166;font-size:22px;margin-top:4px}
canvas{display:block;width:100%;height:auto;background:#151d3b;border:3px solid #ffd166;border-radius:15px;touch-action:none}
button{background:#ffd166;color:#242039;border:0;border-radius:12px;padding:12px 18px;margin:6px 3px;font-size:15px;font-weight:bold;cursor:pointer;touch-action:none}
.tip{color:#c4cce5;font-size:13px;line-height:1.6}
.status{color:#ffd166;font-size:18px;font-weight:bold;min-height:28px}
</style></head><body><div class="wrap">
<div class="stats">
<div class="stat">🏆 分數<b id="score">0</b></div>
<div class="stat">❤️ 生命<b id="lives">3</b></div>
<div class="stat">⚡ 等級<b id="level">1</b></div>
<div class="stat">👑 最高分<b id="best">0</b></div>
</div>
<canvas id="game" width="800" height="520"></canvas>
<div><button onclick="startGame()">▶ 開始</button><button onclick="pauseGame()">⏸ 暫停 / 繼續</button><button onclick="restartGame()">🔄 重新開始</button></div>
<div><button id="left">⬅ 左移</button><button id="right">右移 ➡</button></div>
<p class="tip">電腦：← → 或 A、D。手機：按住左右按鈕，或在畫面拖曳人物。</p>
<div class="status" id="message">按下「開始」開始遊戲！</div>
</div>
<script>
const PLAYER_IMAGE=PLAYER_PLACEHOLDER, CIGARETTE_IMAGE=CIGARETTE_PLACEHOLDER;
const canvas=document.getElementById("game"),ctx=canvas.getContext("2d");
const playerImg=new Image(),cigImg=new Image();
if(PLAYER_IMAGE)playerImg.src=PLAYER_IMAGE;
if(CIGARETTE_IMAGE)cigImg.src=CIGARETTE_IMAGE;
let player={x:360,y:405,w:80,h:100},items=[],particles=[],keys={};
let score=0,lives=3,level=1,best=Number(localStorage.getItem("catchBest")||0);
let running=false,paused=false,gameOver=false,lastSpawn=0,lastTime=0,anim=0,jump=0,dir=0;
function stats(){scoreEl.textContent=score;livesEl.textContent=lives;levelEl.textContent=level;bestEl.textContent=best;}
const scoreEl=document.getElementById("score"),livesEl=document.getElementById("lives"),levelEl=document.getElementById("level"),bestEl=document.getElementById("best");
function bg(){
 let g=ctx.createLinearGradient(0,0,0,520);g.addColorStop(0,"#101832");g.addColorStop(1,"#26385e");
 ctx.fillStyle=g;ctx.fillRect(0,0,800,520);
 for(let i=0;i<90;i++){ctx.globalAlpha=.25+(i%5)*.1;ctx.fillStyle="white";ctx.fillRect((i*137)%800,(i*79)%490,2,2);}
 ctx.globalAlpha=1;ctx.fillStyle="#34465b";ctx.fillRect(0,500,800,20);
}
function drawPlayer(){
 anim+=dir?.18:.035;let bob=Math.sin(anim)*2,tilt=dir*.12;
 ctx.save();ctx.translate(player.x+player.w/2,player.y+player.h/2+bob-jump);ctx.rotate(tilt);
 if(PLAYER_IMAGE&&playerImg.complete&&playerImg.naturalWidth)ctx.drawImage(playerImg,-player.w/2,-player.h/2,player.w,player.h);
 else{ctx.font="65px Arial";ctx.textAlign="center";ctx.fillText("🧍",0,24);}
 ctx.restore();if(jump>0)jump=Math.max(0,jump-.12);
}
function spawn(){items.push({x:Math.random()*740,y:-70,w:58,h:75,s:2+Math.random()*1.2+level*.35});}
function drawItems(){items.forEach(o=>{if(CIGARETTE_IMAGE&&cigImg.complete&&cigImg.naturalWidth){ctx.drawImage(cigImg,o.x,o.y,o.w,o.h);}else{ctx.font="32px Arial";ctx.fillText("🚬",o.x,o.y+30);}});}
function burst(x,y){for(let i=0;i<12;i++)particles.push({x,y,vx:(Math.random()-.5)*6,vy:(Math.random()-.5)*6,l:1});}
function drawParticles(){particles.forEach(p=>{ctx.globalAlpha=p.l;ctx.fillStyle="#ffd166";ctx.beginPath();ctx.arc(p.x,p.y,4,0,7);ctx.fill();p.x+=p.vx;p.y+=p.vy;p.l-=.035;});ctx.globalAlpha=1;particles=particles.filter(p=>p.l>0);}
function move(d){dir=0;let v=6*d;if(keys.ArrowLeft||keys.a||keys.A){player.x-=v;dir=-1;}if(keys.ArrowRight||keys.d||keys.D){player.x+=v;dir=1;}player.x=Math.max(0,Math.min(800-player.w,player.x));}
function update(t){if(!running||paused||gameOver)return;let d=lastTime?Math.min((t-lastTime)/16.67,2):1;lastTime=t;move(d);
 if(t-lastSpawn>Math.max(350,1100-level*75)){spawn();lastSpawn=t;}
 items.forEach(o=>{o.y+=o.s*d;let hit=o.x<player.x+player.w-8&&o.x+o.w>player.x+8&&o.y+o.h>player.y+10&&o.y<player.y+player.h;
 if(hit&&!o.hit){o.hit=true;score+=10;jump=1.5;burst(o.x+o.w/2,o.y+o.h/2);}else if(o.y>520&&!o.hit){o.hit=true;lives--;}});
 items=items.filter(o=>!o.hit);level=Math.floor(score/50)+1;
 if(score>best){best=score;localStorage.setItem("catchBest",best);}stats();if(lives<=0)end();
}
function render(){bg();drawItems();drawParticles();drawPlayer();if(!running||paused){ctx.fillStyle="rgba(0,0,0,.42)";ctx.fillRect(0,0,800,520);ctx.fillStyle="#ffd166";ctx.font="bold 38px Arial";ctx.textAlign="center";ctx.fillText(gameOver?"GAME OVER":paused?"PAUSED":"READY?",400,250);}}
function startGame(){if(gameOver){restartGame();return;}running=true;paused=false;lastTime=0;document.getElementById("message").textContent="遊戲開始！";}
function pauseGame(){if(!running)return;paused=!paused;lastTime=0;document.getElementById("message").textContent=paused?"遊戲暫停":"繼續挑戰！";}
function restartGame(){score=0;lives=3;level=1;items=[];particles=[];player.x=360;running=true;paused=false;gameOver=false;lastSpawn=0;lastTime=0;jump=0;stats();document.getElementById("message").textContent="重新開始！";}
function end(){running=false;gameOver=true;document.getElementById("message").textContent="遊戲結束！最終分數："+score+" 分";}
document.addEventListener("keydown",e=>{keys[e.key]=true;if(["ArrowLeft","ArrowRight"," "].includes(e.key))e.preventDefault();if(e.key===" "&&!e.repeat)pauseGame();});
document.addEventListener("keyup",e=>keys[e.key]=false);
function bind(id,key){let b=document.getElementById(id);b.addEventListener("pointerdown",e=>{e.preventDefault();keys[key]=true;});["pointerup","pointerleave","pointercancel"].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false));}
bind("left","ArrowLeft");bind("right","ArrowRight");
function pointer(e){let r=canvas.getBoundingClientRect();player.x=(e.clientX-r.left)*800/r.width-player.w/2;player.x=Math.max(0,Math.min(800-player.w,player.x));}
canvas.addEventListener("pointerdown",e=>{canvas.setPointerCapture(e.pointerId);pointer(e);});
canvas.addEventListener("pointermove",e=>{if(e.pointerType==="touch"||e.buttons===1)pointer(e);});
function loop(t){update(t);render();requestAnimationFrame(loop);}stats();requestAnimationFrame(loop);
</script></body></html>
"""
html=html.replace("PLAYER_PLACEHOLDER", player_js).replace("CIGARETTE_PLACEHOLDER", cig_js)
components.html(html, height=760, scrolling=False)
